import { componentAttrs } from "../_utils/component.helper";

function serialiseUrl(url) {
    if (url instanceof URL) {
        return url.href;
    }
    return url ?? '';
}

function serialiseCtx(ctx) {
    return {
        ...ctx,
        url: serialiseUrl(ctx?.url),
        note: ctx?.editor
            ? 'In Page Builder, ctx.url is usually the DXP preview URL, not the public site URL.'
            : undefined,
    };
}

function normaliseIdArgs(assetIdOverride, attributes, ctxAssetId) {
    const assetId = assetIdOverride || ctxAssetId || '';
    const attrs = Array.isArray(attributes) ? attributes.filter(Boolean) : [];
    return [String(assetId), attrs];
}

function normaliseUrlArgs(urlOverride, attributes, ctxUrl) {
    const url = serialiseUrl(urlOverride || ctxUrl);
    const attrs = Array.isArray(attributes) ? attributes.filter(Boolean) : [];
    return [url, attrs];
}

function settleResult(settled) {
    if (settled.status === 'fulfilled') {
        return {ok: true, data: settled.value};
    }

    const reason = settled.reason;
    return {
        ok: false,
        error: reason?.message ?? String(reason),
    };
}

function formatCall(name, args) {
    return `${name}(${args.map((arg) => JSON.stringify(arg)).join(', ')})`;
}

export default {
    async main(input = {}, info) {
        const {resolveUriArg = '', rawUriArg = '', assetIdOverride = '', urlOverride = '', attributes = []} = input;
        const {env, ctx, fns} = info;
        const ctxDisplay = serialiseCtx(ctx);
        const byIdArgs = normaliseIdArgs(assetIdOverride, attributes, ctx?.assetId);
        const byUrlArgs = normaliseUrlArgs(urlOverride, attributes, ctx?.url);

        const resolveUriPromise = resolveUriArg
            ? fns.resolveUri(resolveUriArg)
            : Promise.resolve({
                  skipped: true,
                  reason: 'No resolveUriArg provided. resolveUri requires a matrix-asset-uri, not ctx.url.',
              });

        const resolveRawUriPromise = rawUriArg
            ? fns.resolveUri(rawUriArg)
            : Promise.resolve({skipped: true, reason: 'No rawUriArg provided.'});

        const resolveByIdPromise = byIdArgs[0]
            ? fns.resolveMatrixAssetById(byIdArgs[0], byIdArgs[1])
            : Promise.resolve({skipped: true, reason: 'No asset ID available in override or ctx.assetId.'});

        const resolveByUrlPromise = byUrlArgs[0]
            ? fns.resolveMatrixAssetByUrl(byUrlArgs[0], byUrlArgs[1])
            : Promise.resolve({skipped: true, reason: 'No URL available in override or ctx.url.'});

        const [resolveUriResult, resolveRawUriResult, resolveMatrixAssetByIdResult, resolveMatrixAssetByUrlResult] = await Promise.allSettled([
            resolveUriPromise,
            resolveRawUriPromise,
            resolveByIdPromise,
            resolveByUrlPromise,
        ]);

        const displayResults = {
            byIdArgs,
            byUrlArgs,
            resolveUri: {
                call: resolveUriArg ? formatCall('resolveUri', [resolveUriArg]) : '(skipped)',
                result: settleResult(resolveUriResult),
            },
            resolveUriRaw: {
                call: rawUriArg ? formatCall('resolveUri', [rawUriArg]) : '(skipped)',
                note: 'Free-text variant of resolveUri, bypassing the Asset Tree picker -- for testing non-standard URI suffixes.',
                result: settleResult(resolveRawUriResult),
            },
            resolveMatrixAssetById: {
                call: formatCall('resolveMatrixAssetById', byIdArgs),
                result: settleResult(resolveMatrixAssetByIdResult),
            },
            resolveMatrixAssetByUrl: {
                call: formatCall('resolveMatrixAssetByUrl', byUrlArgs),
                note:
                    ctx?.editor && !urlOverride
                        ? 'Using ctx.url default. Set urlOverride to test with the public site URL.'
                        : undefined,
                result: settleResult(resolveMatrixAssetByUrlResult),
            },
        };

        return /*html*/ `<div ${componentAttrs("dxp-inspector", input)}>
            <details open>
                <summary>DXP Inspector</summary>
                <details open>
                    <summary>ctx</summary>
                    <pre><code>${JSON.stringify(ctxDisplay, null, 2)}</code></pre>
                </details>
                <details open>
                    <summary>fns</summary>
                    <small>${Object.keys(fns).join(', ')}</small>
                    <pre><code>${JSON.stringify(displayResults, null, 2)}</code></pre>
                </details>
                <details open>
                    <summary>env</summary>
                    <small>Component is configured for <code>INSPECTOR_ENV</code> you can set that to test if you need to</small>
                    <pre><code>${JSON.stringify(env, null, 2)}</code></pre>
                </details>
            </details>
        </div>`;
    },
};
